// Onboarding step machine: draw -> chat -> why -> recommend -> roadmap -> claim -> done.
// Deterministic in both modes so onboarding never depends on a model call.
//   chat: six questions, each filling one vision-board field (free text always accepted, chips are suggestions).
//   why: what drives the learner and what they already bring. Stored as board.why and board.background.
//   recommend: the custom path first (generated by the core from the answers), then up to two authored careers.
import type { ChatMessage, Career, Company, FtuxStep, FtuxTurn, FtuxView, Scenario, User, VisionBoard } from "@pw/shared";
import { CUSTOM_CAREER_ID, PLANS } from "@pw/shared";
import type { FtuxSession } from "../../contracts.ts";
import { overlap } from "../text.ts";

export const DRAW_PROMPT = "Draw what your dream job looks like. Stick figures welcome.";
export const WHY_PROMPT = "What's driving you, and what do you already bring? (studies, jobs, projects)";
const CUSTOM_COLOR = "#7B6CF6";
const NOT_SURE = "Not sure yet";

interface Question {
  prompt: string;
  chips: string[];
  field: "targetRole" | "level" | "industry" | "companyType" | "location" | "timeline";
}

const QUESTIONS: Question[] = [
  {
    prompt: "What role are you aiming for? Type any job title.",
    chips: ["Software Engineer", "Data Analyst", "Product Manager", "UX Designer", "Marketing Manager", NOT_SURE],
    field: "targetRole",
  },
  { prompt: "How senior are you today?", chips: ["Intern", "Junior", "Mid-level", "Senior"], field: "level" },
  { prompt: "Which industry do you want to work in?", chips: ["Tech", "Energy", "Healthcare", "Finance", "Retail", "Education"], field: "industry" },
  { prompt: "What kind of company?", chips: ["Startup", "Scale-up", "Enterprise", "Non-profit"], field: "companyType" },
  { prompt: "Where would you like to work?", chips: ["Remote", "Calgary", "Toronto", "New York", "London"], field: "location" },
  { prompt: "How soon do you want to land it?", chips: ["1 month", "3 months", "6 months"], field: "timeline" },
];

const FREE_CREDITS = PLANS.find((p) => p.id === "free")?.credits ?? 10_000;

function humanise(id: string): string {
  return id
    .split(/[-_]/)
    .filter(Boolean)
    .map((w) => w[0].toUpperCase() + w.slice(1))
    .join(" ");
}

function titleCase(text: string): string {
  return text
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .map((w) => (w.length > 1 && w === w.toUpperCase() ? w : w[0].toUpperCase() + w.slice(1).toLowerCase()))
    .join(" ");
}

function baseView(sessionId: string, patch: Partial<FtuxView>): FtuxView {
  return {
    sessionId,
    step: "draw",
    prompt: DRAW_PROMPT,
    chips: [],
    messages: [],
    board: {},
    recommendations: [],
    roadmap: null,
    claim: null,
    ...patch,
  };
}

function npcMessage(sessionId: string, index: number, text: string): ChatMessage {
  return { id: `${sessionId}-m${index}`, role: "npc", text, at: new Date().toISOString() };
}

function learnerMessage(sessionId: string, index: number, text: string): ChatMessage {
  return { id: `${sessionId}-m${index}`, role: "learner", text, at: new Date().toISOString() };
}

export function ftuxStartMock(i: { sessionId: string }): FtuxView {
  return baseView(i.sessionId, { step: "draw", prompt: DRAW_PROMPT });
}

function chatView(sessionId: string, messages: ChatMessage[], board: Partial<VisionBoard>, qIndex: number): FtuxView {
  const q = QUESTIONS[qIndex];
  return baseView(sessionId, { step: "chat", prompt: q.prompt, chips: q.chips, messages, board });
}

/** The role used for the custom path and its title. "Not sure yet" or empty becomes a business analyst role. */
export function customRoleTitle(board: Partial<VisionBoard>): string {
  const role = (board.targetRole ?? "").trim();
  if (role && role !== NOT_SURE) return titleCase(role);
  const industry = (board.industry ?? "").trim();
  return industry ? `${titleCase(industry)} Business Analyst` : "Business Analyst";
}

/** The custom path is always first. Its id is CUSTOM_CAREER_ID until the core generates the real path. */
export function customRecommendation(board: Partial<VisionBoard>): FtuxView["recommendations"][number] {
  const title = customRoleTitle(board);
  // The learner's own words, quoted as they typed them: free text never fits a sentence template cleanly.
  const answers = [board.level, board.industry, board.companyType, board.location, board.timeline]
    .map((v) => (v ?? "").trim().replace(/[.\s]+$/, ""))
    .filter((v) => v && v !== NOT_SURE);
  const reason = answers.length
    ? `Three projects written for you, from your answers: ${answers.join(" · ")}.`
    : "Three projects written for you, at companies and with managers made for this path.";
  return {
    careerId: CUSTOM_CAREER_ID,
    kind: "custom",
    title,
    match: 100,
    reason,
    color: CUSTOM_COLOR,
  };
}

/** Up to two authored careers with keyword overlap against the role and industry. Generated careers never appear. */
export function authoredRecommendations(careers: Career[], board: Partial<VisionBoard>): FtuxView["recommendations"] {
  const role = (board.targetRole ?? "").trim();
  const roleQuery = role && role !== NOT_SURE ? role : "";
  const query = [roleQuery, board.industry ?? ""].filter(Boolean).join(" ");
  if (!query) return [];
  return careers
    .filter((c) => !c.generated)
    .map((c, index) => ({ c, index, hits: overlap(`${c.title} ${c.tagline} ${c.skills.join(" ")}`, query) }))
    .filter((x) => x.hits > 0)
    .sort((a, b) => b.hits - a.hits || a.index - b.index)
    .slice(0, 2)
    .map(({ c, hits }) => ({
      careerId: c.id,
      title: c.title,
      reason: roleQuery && overlap(`${c.title} ${c.tagline}`, roleQuery) > 0 ? `Matches your ${roleQuery} goal: ${c.tagline}` : `${c.tagline}`,
      match: Math.min(95, 55 + hits * 10),
      kind: "authored" as const,
      color: c.color,
    }));
}

/** The full recommendation list shown on the recommend step. */
export function recommendationsFor(careers: Career[], board: Partial<VisionBoard>): FtuxView["recommendations"] {
  return [customRecommendation(board), ...authoredRecommendations(careers, board)];
}

export function ftuxTurnMock(i: {
  session: FtuxSession;
  turn: FtuxTurn;
  user: User;
  careers: Career[];
  scenarios: Scenario[];
  companies: Company[];
}): { view: FtuxView; memory: Record<string, unknown>; board: Partial<VisionBoard>; careerId?: string } {
  const { session, turn, careers, scenarios, companies } = i;
  const current = session.view;
  const memory: Record<string, unknown> = { ...session.memory };
  const board: Partial<VisionBoard> = { ...current.board };
  const stay = (): { view: FtuxView; memory: Record<string, unknown>; board: Partial<VisionBoard> } => ({
    view: current,
    memory,
    board: current.board,
  });
  const messages = [...current.messages];
  const nextIndex = () => messages.length + 1;

  switch (current.step as FtuxStep) {
    case "draw": {
      if (turn.kind !== "DRAWN" && turn.kind !== "CONTINUE") return stay();
      if (turn.kind === "DRAWN") {
        if (!turn.dataUrl.startsWith("data:image/")) return stay();
        board.drawingDataUrl = turn.dataUrl;
      }
      memory.qIndex = 0;
      messages.push(npcMessage(session.id, nextIndex(), "Thanks, that gives me a picture. Let's make it concrete."));
      messages.push(npcMessage(session.id, nextIndex(), QUESTIONS[0].prompt));
      return { view: chatView(session.id, messages, board, 0), memory, board };
    }

    case "chat": {
      if (turn.kind !== "MESSAGE") return stay();
      const text = turn.text.trim().slice(0, 120);
      if (!text) return stay();
      const qIndex = typeof memory.qIndex === "number" ? memory.qIndex : 0;
      if (qIndex < 0 || qIndex >= QUESTIONS.length) return stay();
      messages.push(learnerMessage(session.id, nextIndex(), text));
      board[QUESTIONS[qIndex].field] = text;

      const answered = qIndex + 1;
      memory.qIndex = answered;
      if (answered < QUESTIONS.length) {
        messages.push(npcMessage(session.id, nextIndex(), QUESTIONS[answered].prompt));
        return { view: chatView(session.id, messages, board, answered), memory, board };
      }

      messages.push(npcMessage(session.id, nextIndex(), "Thanks, that's a clear picture of where you're headed."));
      messages.push(npcMessage(session.id, nextIndex(), WHY_PROMPT));
      const view = baseView(session.id, { step: "why", prompt: WHY_PROMPT, messages, board });
      return { view, memory, board };
    }

    case "why": {
      if (turn.kind !== "WHY") return stay();
      const text = turn.text.trim().slice(0, 400);
      if (!text) return stay();
      board.why = text;
      board.background = text;
      const view = baseView(session.id, {
        step: "recommend",
        prompt: "Here are the paths that fit you best. Pick one to see your roadmap.",
        messages,
        board,
        recommendations: recommendationsFor(careers, board),
      });
      return { view, memory, board };
    }

    case "recommend": {
      if (turn.kind !== "SELECT_CAREER") return stay();
      const career = careers.find((c) => c.id === turn.careerId);
      if (!career) return stay();
      const roadmapScenarios = scenarios
        .filter((s) => s.careerId === career.id)
        .sort((a, b) => a.order - b.order)
        .map((s) => ({
          scenarioId: s.id,
          title: s.title,
          company: companies.find((c) => c.id === s.companyId)?.name ?? humanise(s.companyId),
          estMinutes: s.estMinutes,
        }));
      memory.careerId = career.id;
      const view = baseView(session.id, {
        step: "roadmap",
        prompt: `Your ${career.title} roadmap. Here's the first project and what follows.`,
        messages,
        board,
        recommendations: current.recommendations,
        roadmap: { careerId: career.id, scenarios: roadmapScenarios },
      });
      return { view, memory, board, careerId: career.id };
    }

    case "roadmap": {
      if (turn.kind !== "CONTINUE") return stay();
      const view = baseView(session.id, {
        step: "claim",
        prompt: "Claim your starter credits to begin.",
        messages,
        board,
        recommendations: current.recommendations,
        roadmap: current.roadmap,
        claim: { credits: FREE_CREDITS, claimed: false },
      });
      return { view, memory, board };
    }

    case "claim": {
      if (turn.kind !== "CLAIM") return stay();
      const view = baseView(session.id, {
        step: "done",
        prompt: "You're all set. Your first project is waiting on the map.",
        messages,
        board,
        recommendations: current.recommendations,
        roadmap: current.roadmap,
        claim: { credits: current.claim?.credits ?? FREE_CREDITS, claimed: true },
      });
      return { view, memory, board };
    }

    case "done":
    default:
      return stay();
  }
}
